:root {
  --primary-color: #171717;
  --accent-color: #0072F5;
  --bg-color: #FAFAFA;
  --text-muted: #666666;
  --border-color: #EAEAEA;
  --card-bg: #FFFFFF;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-color);
  color: var(--primary-color);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Header */
.site-header {
  background-color: var(--bg-color);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  font-size: 1.125rem;
  letter-spacing: -0.02em;
}

.main-nav {
  display: flex;
  align-items: center;
  gap: 24px;
  height: 100%;
}

.nav-link, .nav-btn {
  font-family: inherit;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-muted);
  background: none;
  border: none;
  cursor: pointer;
  transition: color 0.2s;
  height: 100%;
  display: flex;
  align-items: center;
}

.nav-link:hover, .nav-btn:hover, .nav-btn[aria-expanded="true"] {
  color: var(--primary-color);
}

.chevron {
  margin-left: 4px;
  font-size: 0.75rem;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.action-link {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-muted);
}
.action-link:hover { color: var(--primary-color); }

.btn {
  font-family: inherit;
  font-weight: 500;
  font-size: 0.875rem;
  padding: 8px 16px;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s;
  border: 1px solid transparent;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.btn-primary {
  background-color: var(--primary-color);
  color: #fff;
}
.btn-primary:hover { background-color: #333; }

.btn-secondary {
  background-color: transparent;
  border-color: var(--border-color);
  color: var(--primary-color);
}
.btn-secondary:hover { background-color: var(--border-color); }

.btn-outline {
  background-color: transparent;
  border-color: #fff;
  color: #fff;
}
.btn-outline:hover { background-color: rgba(255,255,255,0.1); }

/* Dropdowns */
.has-dropdown {
  position: relative;
  height: 100%;
}

.dropdown-menu {
  position: absolute;
  top: 100%;
  left: -20px;
  background-color: #fff;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.08);
  opacity: 0;
  visibility: hidden;
  transform: translateY(10px);
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  padding: 24px;
  z-index: 200;
}

.has-dropdown.active .dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mega-menu {
  width: 700px;
  left: 50%;
  transform: translateX(-50%) translateY(10px);
}
.has-dropdown.active .mega-menu {
  transform: translateX(-50%) translateY(0);
}

.mega-menu-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.menu-column h4, .menu-group h4 {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  margin-bottom: 16px;
}

.menu-column a {
  display: block;
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: 16px;
  line-height: 1.4;
}
.menu-column a strong {
  color: var(--primary-color);
  font-weight: 500;
}
.menu-column a:hover strong {
  color: var(--accent-color);
}

.standard-menu {
  width: 500px;
  display: flex;
  gap: 48px;
}
.menu-group a {
  display: block;
  font-size: 0.875rem;
  color: var(--primary-color);
  margin-bottom: 12px;
  font-weight: 500;
}
.menu-group a:hover {
  color: var(--accent-color);
}

/* Blog Hero */
.blog-hero {
  padding: 80px 0 40px;
}
.page-title {
  font-size: 3rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  margin-bottom: 16px;
}
.page-subtitle {
  font-size: 1.25rem;
  color: var(--text-muted);
  max-width: 600px;
}

/* Featured Articles */
.featured-articles {
  padding: 0 0 64px;
}
.featured-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 24px;
}

.featured-card {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow 0.2s, transform 0.2s;
}
.featured-card:hover {
  box-shadow: 0 12px 24px rgba(0,0,0,0.06);
  transform: translateY(-2px);
}

.card-content {
  padding: 32px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.meta {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.875rem;
  margin-bottom: 16px;
}
.tag {
  color: var(--accent-color);
  font-weight: 500;
  background: rgba(0, 114, 245, 0.1);
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 0.75rem;
}
.date {
  color: var(--text-muted);
}

.featured-card h2, .featured-card h3 {
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
  line-height: 1.2;
}
.main-feature h2 { font-size: 2.5rem; }
.secondary-feature h3 { font-size: 1.5rem; }

.excerpt {
  color: var(--text-muted);
  margin-bottom: 24px;
  font-size: 1rem;
  line-height: 1.6;
}
.main-feature .excerpt { font-size: 1.125rem; }

.stats-box {
  background-color: var(--bg-color);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 24px;
  margin-bottom: 24px;
}
.stats-box h4 {
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  margin-bottom: 12px;
}
.stats-box ul {
  list-style: none;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.stats-box li {
  font-size: 0.875rem;
  color: var(--primary-color);
}
.stats-box strong {
  display: block;
  font-size: 1.5rem;
  color: var(--accent-color);
  margin-bottom: 4px;
}

.author {
  margin-top: auto;
  display: flex;
  align-items: center;
  gap: 12px;
}
.avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background-color: var(--primary-color);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 600;
}
.author-name {
  font-weight: 500;
  font-size: 0.875rem;
}

.secondary-features {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* Latest News section */
.latest-news-section {
  padding: 64px 0;
  border-top: 1px solid var(--border-color);
}
.controls-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 40px;
  gap: 24px;
  flex-wrap: wrap;
}

.category-filters {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.pill {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  color: var(--text-muted);
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  font-family: inherit;
}
.pill:hover {
  border-color: #ccc;
  color: var(--primary-color);
}
.pill.active {
  background: var(--primary-color);
  color: #fff;
  border-color: var(--primary-color);
}

.search-container {
  position: relative;
  width: 280px;
}
.search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
}
#search-input {
  width: 100%;
  padding: 10px 16px 10px 36px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  font-family: inherit;
  font-size: 0.875rem;
  outline: none;
  transition: border-color 0.2s;
}
#search-input:focus {
  border-color: var(--primary-color);
}

.no-results {
  text-align: center;
  padding: 40px;
  color: var(--text-muted);
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  margin-bottom: 40px;
}
.no-results.hidden {
  display: none;
}

.posts-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-bottom: 48px;
}

.post-card {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  transition: box-shadow 0.2s, transform 0.2s;
}
.post-card.hidden, .post-card.hidden-post {
  display: none;
}
.post-card:hover {
  box-shadow: 0 8px 16px rgba(0,0,0,0.04);
  transform: translateY(-2px);
}
.post-card h3 {
  font-size: 1.25rem;
  margin-bottom: 12px;
  line-height: 1.3;
}
.post-card .excerpt {
  font-size: 0.875rem;
  margin-bottom: 24px;
}

.load-more-container {
  text-align: center;
}
.load-more-container.hidden {
  display: none;
}

/* CTA Banner */
.cta-banner {
  background-color: var(--primary-color);
  color: #fff;
  padding: 80px 0;
  margin-top: 64px;
}
.cta-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.cta-content h2 {
  font-size: 2rem;
  font-weight: 400;
  line-height: 1.3;
  margin-bottom: 32px;
}
.cta-content strong {
  font-weight: 700;
}
.cta-actions {
  display: flex;
  gap: 16px;
}
.cta-actions .btn-primary {
  background-color: #fff;
  color: var(--primary-color);
}
.cta-actions .btn-primary:hover {
  background-color: #f0f0f0;
}
.cta-actions .btn-secondary {
  border-color: rgba(255,255,255,0.3);
  color: #fff;
}
.cta-actions .btn-secondary:hover {
  background-color: rgba(255,255,255,0.1);
}

.cta-enterprise {
  background-color: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 12px;
  padding: 40px;
}
.cta-enterprise h3 {
  font-size: 1.5rem;
  margin-bottom: 12px;
}
.cta-enterprise p {
  color: rgba(255,255,255,0.7);
  margin-bottom: 24px;
}

/* Footer */
.site-footer {
  background-color: #000;
  color: #fff;
  padding: 80px 0 40px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 24px;
  margin-bottom: 64px;
}
.footer-col h4 {
  font-size: 0.875rem;
  margin-bottom: 20px;
}
.footer-col h4.mt { margin-top: 32px; }

.footer-col a {
  display: block;
  color: rgba(255,255,255,0.6);
  font-size: 0.875rem;
  margin-bottom: 12px;
}
.footer-col a:hover {
  color: #fff;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 32px;
  flex-wrap: wrap;
  gap: 24px;
}
.logo-status {
  display: flex;
  align-items: center;
  gap: 24px;
}
.status-indicator {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
}
.dot {
  width: 8px;
  height: 8px;
  background-color: #0072F5;
  border-radius: 50%;
  display: inline-block;
}
.footer-links, .social-links {
  display: flex;
  gap: 24px;
}
.footer-links a, .social-links a {
  color: rgba(255,255,255,0.6);
  font-size: 0.875rem;
}
.footer-links a:hover, .social-links a:hover {
  color: #fff;
}

/* Responsive */
@media (max-width: 1024px) {
  .featured-grid { grid-template-columns: 1fr; }
  .secondary-features { flex-direction: row; }
  .secondary-features > * { flex: 1; }
  .posts-grid { grid-template-columns: repeat(2, 1fr); }
  .cta-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); gap: 48px 24px; }
  .main-nav, .header-actions { display: none; } /* Simplified for demo, a real app would have a hamburger menu */
}
@media (max-width: 768px) {
  .secondary-features { flex-direction: column; }
  .posts-grid { grid-template-columns: 1fr; }
  .controls-bar { flex-direction: column; align-items: stretch; }
  .search-container { width: 100%; }
  .stats-box ul { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .cta-actions { flex-direction: column; }
}

