  color: var(--primary-color);
}
.stats-box strong {
  display: block;
  font-size: 1.5rem;
  color: var(--accent-color);
  margin-bottom: 4px;
}

.author {
  margin-top: auto;
  display: flex;
  align-items: center;
  gap: 12px;
}
.avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background-color: var(--primary-color);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 600;
}
.author-name {
  font-weight: 500;
  font-size: 0.875rem;
}

.secondary-features {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* Latest News section */
.latest-news-section {
  padding: 64px 0;
  border-top: 1px solid var(--border-color);
}
.controls-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 40px;
  gap: 24px;
  flex-wrap: wrap;
}

.category-filters {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.pill {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  color: var(--text-muted);
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  font-family: inherit;
}
.pill:hover {
  border-color: #ccc;
  color: var(--primary-color);
}
.pill.active {
  background: var(--primary-color);
  color: #fff;
  border-color: var(--primary-color);
}

.search-container {
  position: relative;
  width: 280px;
}
.search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
}
#search-input {
  width: 100%;
  padding: 10px 16px 10px 36px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  font-family: inherit;
  font-size: 0.875rem;
  outline: none;
  transition: border-color 0.2s;
}
#search-input:focus {
  border-color: var(--primary-color);
}

.no-results {
  text-align: center;
  padding: 40px;
  color: var(--text-muted);
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  margin-bottom: 40px;
}
.no-results.hidden {
  display: none;
}

.posts-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-bottom: 48px;
}

.post-card {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  transition: box-shadow 0.2s, transform 0.2s;
}
.post-card.hidden, .post-card.hidden-post {
  display: none;
}
.post-card:hover {
  box-shadow: 0 8px 16px rgba(0,0,0,0.04);
  transform: translateY(-2px);
}
.post-card h3 {
  font-size: 1.25rem;
  margin-bottom: 12px;
  line-height: 1.3;
}
.post-card .excerpt {
  font-size: 0.875rem;
  margin-bottom: 24px;
}

.load-more-container {
  text-align: center;
}
.load-more-container.hidden {
  display: none;
}

/* CTA Banner */
.cta-banner {
  background-color: var(--primary-color);
  color: #fff;
  padding: 80px 0;
  margin-top: 64px;
}
.cta-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.cta-content h2 {
  font-size: 2rem;
  font-weight: 400;
  line-height: 1.3;
  margin-bottom: 32px;
}
.cta-content strong {
  font-weight: 700;
}
.cta-actions {
  display: flex;
  gap: 16px;
}
.cta-actions .btn-primary {
  background-color: #fff;
  color: var(--primary-color);
}
.cta-actions .btn-primary:hover {
  background-color: #f0f0f0;
}
.cta-actions .btn-secondary {
  border-color: rgba(255,255,255,0.3);
  color: #fff;
}
.cta-actions .btn-secondary:hover {
  background-color: rgba(255,255,255,0.1);
}

.cta-enterprise {
  background-color: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 12px;
  padding: 40px;
}
.cta-enterprise h3 {
  font-size: 1.5rem;
  margin-bottom: 12px;
}
.cta-enterprise p {
  color: rgba(255,255,255,0.7);
  margin-bottom: 24px;
}

/* Footer */
.site-footer {
  background-color: #000;
  color: #fff;
  padding: 80px 0 40px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 24px;
  margin-bottom: 64px;
}
.footer-col h4 {
  font-size: 0.875rem;
  margin-bottom: 20px;
}
.footer-col h4.mt { margin-top: 32px; }

.footer-col a {
  display: block;
  color: rgba(255,255,255,0.6);
  font-size: 0.875rem;
  margin-bottom: 12px;
}
.footer-col a:hover {
  color: #fff;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 32px;
  flex-wrap: wrap;
  gap: 24px;
}
.logo-status {
  display: flex;
  align-items: center;
  gap: 24px;
}
.status-indicator {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
}
.dot {
  width: 8px;
  height: 8px;
  background-color: #0072F5;
  border-radius: 50%;
  display: inline-block;
}
.footer-links, .social-links {
  display: flex;
  gap: 24px;
}
.footer-links a, .social-links a {
  color: rgba(255,255,255,0.6);
  font-size: 0.875rem;
}
.footer-links a:hover, .social-links a:hover {
  color: #fff;
}

/* Responsive */
@media (max-width: 1024px) {
  .featured-grid { grid-template-columns: 1fr; }
  .secondary-features { flex-direction: row; }
  .secondary-features > * { flex: 1; }
  .posts-grid { grid-template-columns: repeat(2, 1fr); }
  .cta-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); gap: 48px 24px; }
  .main-nav, .header-actions { display: none; } /* Simplified for demo, a real app would have a hamburger menu */
}
@media (max-width: 768px) {
  .secondary-features { flex-direction: column; }
  .posts-grid { grid-template-columns: 1fr; }
  .controls-bar { flex-direction: column; align-items: stretch; }
  .search-container { width: 100%; }
  .stats-box ul { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .cta-actions { flex-direction: column; }
}

